using System;
using System.Collections.Generic;
using System.Linq;
namespace Dafeiyu
{
    internal sealed class OnboardingLesson
    {
        public string Id, Title, Text, Target, Action, Branch;
        public int Chapter;
    }
    internal static class OnboardingLessons
    {
        internal static readonly string[] Chapters = { "伙伴与入口", "人格", "陪伴方式", "拖动", "右键菜单", "动作轮盘", "点击互动", "双击快聊", "文字模型", "语音识别", "回复朗读", "Live 通话", "主动问候", "快捷键与记录", "完整对话与项目", "工作设置", "网络与完成" };
        internal static readonly OnboardingLesson[] All = Build();
        static OnboardingLesson[] Build()
        {
            var items = new List<OnboardingLesson>();
            Action<int, string, string, string, string, string, string> add = (chapter, id, title, text, target, action, branch) => items.Add(new OnboardingLesson { Chapter = chapter, Id = id, Title = title, Text = text, Target = target, Action = action, Branch = branch });
            add(0, "welcome", "开始之前", "这份引导会带您逐步认识桌面伙伴，不必一次完成所有设置。\n\n“跳过本步”：略过当前操作。\n“跳过本章”：略过这一整章，继续后面的内容。\n“稍后继续”：保存进度，下次从这里接着看。\n“结束引导”：退出本次引导，以后可从设置重新打开。\n\n您可以随时使用这些按钮。只有主动点击测试，才会发送请求、播放声音或开启麦克风。", "", "intro", "");
            add(0, "pet.select", "选择伙伴", "应用已内置 E 包完整角色。其他伙伴需要下载完整角色包；引导期间点击列表只会说明下载要求，暂不切换或下载。完成引导后即可选择伙伴，或在设置中全量下载。人格与声音偏好按伙伴分别保存。", "SkinPicker", "read", "");
            add(0, "pet.reopen", "记住设置入口", "以后可以从桌宠右键菜单打开设置，也可从完整对话窗口的齿轮进入。设置左下角“配置引导”可再次打开本教程。", "SkinPicker", "read", "");
            add(1, "persona.read", "阅读当前人格", "人格决定普通聊天的身份、语气与习惯。先阅读高亮输入框；{pet_name} 会替换为当前伙伴名字。工作模式使用独立的工作提示词。", "PersonaPrompt", "read", "");
            add(1, "persona.edit", "修改或恢复人格", "可以只改称呼与回答风格，或保留预设。正文不能为空。恢复预设会替换输入框中的草稿，修改后仍需保存。", "PersonaPrompt", "nonempty", "");
            add(1, "persona.save", "保存人格", "点击下方“保存并继续”保存当前人格。只有保存成功才会前进；保存失败时留在本步并显示原因。", "SavePersona", "persona", "");
            add(2, "behavior.size", "调整桌宠大小", "拖动滑块，观察桌宠大小；这是即时生效的设置。保留当前大小也可以，不会要求你修改每个开关。", "SizeSlider", "read", "");
            add(2, "behavior.follow", "选择视线与散步", "“跟随鼠标”控制视线，“散步”控制自动移动，二者独立。可以按工作习惯开关。", "FollowCursor", "read", "");
            add(2, "behavior.wander", "设置自动散步", "不希望伙伴走动时关闭散步；仍可手动拖动。免打扰会暂停散步。", "Wander", "read", "");
            add(2, "behavior.stumble", "拖放反应", "拖放踉跄控制松手后的反馈，是否有此动作取决于当前外观。关闭不会阻止拖动。思考和工作中仍可拖动、点击互动或打开动作轮盘，结束后恢复当前任务动作。", "StumbleEnabled", "read", "");
            add(2, "behavior.sleep", "自动小憩", "开启后，伙伴空闲一段时间可以进入小憩；互动后恢复。引导期间暂停自动小憩，避免遮住实操。", "AutoSleepEnabled", "read", "");
            add(2, "behavior.top", "设置置顶", "需要伙伴显示在其他窗口上方时开启置顶。若挡住内容，可关闭或拖到屏幕边缘。", "Topmost", "read", "");
            add(2, "behavior.startup", "是否开机启动", "只有你主动开启“自启”才会注册启动项。可以保持关闭，之后在此处修改。", "AutoStart", "read", "");
            add(3, "gesture.drag", "实操：拖动伙伴", "在角色不透明的身体上按住鼠标左键，移动一小段再松开。实际移动后才会解锁下一步；不方便操作可跳过。", "GuidePet", "gesture", "");
            add(4, "gesture.menu", "实操：右键菜单", "右击伙伴身体，查看菜单；点击菜单外空白处收起。本步仅练习打开菜单，菜单中的业务操作暂时禁用。", "GuidePet", "gesture", "");
            add(5, "gesture.wheel", "实操：动作轮盘", "在伙伴身体按鼠标中键，打开轮盘后选择一个动作。轮盘会避开屏幕边缘；选中动作才算完成。", "GuidePet", "gesture", "");
            add(6, "gesture.click", "实操：单击互动", "单击伙伴的头或身体，稍等摸头或轻戳动画出现。单击与双击区分，双击打开快聊不计入本步。", "GuidePet", "gesture", "");
            add(7, "gesture.quick", "实操：双击快速对话", "在伙伴身体快速双击鼠标左键，打开快速对话。本步仅预览，发送与录音暂时禁用；可以用右上角关闭。关闭后再次打开会新建空白对话，不带上一次上下文；旧记录可从完整对话的“快速对话”分组打开。", "GuidePet", "gesture", "");
            add(8, "text.provider", "新增文字服务商", "点击“新增”，选择你的服务商。没有账号可跳过本章；取消选择不会删除已填内容。一个服务商可保存多个模型，当前模型只能选择一个。", "AddTextProvider", "read", "");
            add(8, "text.url", "核对文字接口地址", "展开连接设置，核对服务商提供的基础地址。使用厂商官方或自己的兼容接口；不要把网页聊天地址填到 API 地址中。", "TextServiceUrl", "url", "");
            add(8, "text.protocol", "选择接口协议", "OpenAI Chat Completions 与 Anthropic Messages 使用不同协议。选择服务商要求的协议，不能仅凭模型名字判断。", "TextServiceProtocol", "read", "");
            add(8, "text.key", "填写文字 API Key", "填入该服务商的 API Key。密钥由当前 Windows 用户加密保存；本引导不显示或复制密钥。支持匿名访问的自建服务可留空。", "TextServiceKey", "read", "");
            add(8, "text.proxy", "按需配置文字代理", "只有服务需要代理时才开启。默认本机地址是 http://127.0.0.1:7890，需确保本机代理已运行。这个代理只作用于该服务，不等于更新下载加速。", "TextServiceProxy", "read", "");
            add(8, "text.fetch", "获取可用模型列表", "点击连接区域的“保存并获取模型列表”，或模型区的“获取模型列表”。这会查询服务，不发送聊天内容；获取成功只证明列表接口可用，不代表聊天已验证。", "SaveAndFetchTextModels", "read", "");
            add(8, "text.add", "逐个添加模型", "在获取结果中点击某个模型右侧的添加按钮，逐个添加。弹出的模型窗口可设置显示名、能力和上下文容量，点击保存或添加确认。没有批量框选。", "DiscoveredTextModels", "read", "");
            add(8, "text.manual", "列表不可用时手动添加", "点击“自定义模型”，输入厂商给出的完整模型 ID。列表查询失败不一定代表该模型不能聊天；不确定时先核对账号权限。", "CustomTextModel", "read", "");
            add(8, "text.capacity", "填写模型上下文容量", "在模型的编辑窗口填写厂商公布的上下文 Token 容量。已识别时可以保留自动值；未知可保留 0，运行时使用工作设置中的兜底值。图像、工具能力也应以实际模型为准。", "TextProviderModels", "read", "");
            add(8, "text.capabilities", "核对工具与图片能力", "在模型编辑窗口分别选择工具调用、图片理解的自动／支持／不支持。用户设置优先，其次是当前服务返回的明确元数据；都没有时才沿用未经验证的旧兼容判断。更换服务地址会清除旧元数据。开启不代表服务一定可用，也不会扩大项目权限。", "TextProviderModels", "read", "");
            add(8, "text.select", "选择当前使用模型", "在已添加模型中选择一个作为当前模型。切换模型从下一次请求生效；不会自动发送已有草稿。", "TextProviderModels", "read", "");
            add(8, "text.stream", "是否使用流式回复", "开启后文字逐段显示；有些兼容接口仅支持非流式，遇到空回复或协议错误时可关闭重试。", "TextServiceStreamReplies", "read", "");
            add(8, "text.save", "保存文字配置", "“保存并继续”只保存文字服务这一页，不会连带保存尚未完成的识别、朗读或 Live 配置。", "TextProviderModels", "ai0", "");
            add(8, "text.test", "验证一次真实文字请求", "可点击下方“发送文字测试”：发送一句简短测试，不写入聊天记录。可能产生少量额度消耗；只有收到非空回复才记为测试通过。不测试可跳过。", "TextProviderModels", "text-test", "");
            add(8, "text.help", "文字连接排错", "401/403：核对 Key、账号和模型权限；404：核对接口地址、协议和模型 ID；超时：检查网络与代理。模型列表成功和真实回复成功是两项不同验证。不要把密钥或完整服务响应贴给他人。", "TextProviderModels", "read", "");
            add(9, "asr.intro", "理解语音识别", "ASR 将你的录音转换为文字，然后再交给文字模型。它不负责朗读，也不同于边说边听的 Live。只打字时可以跳过本章。", "AddAsrProvider", "read", "");
            add(9, "asr.provider", "选择识别服务", "点击“新增”选择识别厂商。文字服务的密钥不会自动复用，需确认自己的账号也开通了识别能力。", "AddAsrProvider", "read", "");
            add(9, "asr.url", "核对识别地址", "检查识别服务地址；模型 ID 可编辑，必须是该厂商实际支持的识别模型。预填值只是起点。", "TranscriptionUrl", "url", "");
            add(9, "asr.model", "填写识别模型", "填写识别模型 ID。此页不获取模型列表；不要填入普通文字聊天模型。", "TranscriptionModel", "nonempty", "");
            add(9, "asr.key", "填写识别 Key", "使用拥有语音识别权限的 Key。匿名自建服务可留空。不要依赖文字配置中的 Key 自动生效。", "TranscriptionKey", "read", "");
            add(9, "asr.proxy", "识别服务的代理", "按需开启该服务自己的代理，核对地址与端口。录音上传会经过此连接；只使用你信任的服务。", "TranscriptionProxy", "read", "");
            add(9, "asr.save", "保存识别配置", "保存不会开始录音。之后在聊天输入框点击麦克风才会请求麦克风设备并收音。", "TranscriptionModel", "ai1", "");
            add(9, "asr.operate", "认识录音的停止、发送与取消", "聊天窗口点击麦克风开始听写；停止后识别结果保留为草稿，发送按钮会识别后提交，Esc 取消。先检查识别文字再发送，避免将误识别直接交给模型。", "TranscriptionModel", "read", "");
            add(10, "speech.intro", "先分清三个声音开关", "“TTS 输出”决定是否自动朗读回复；“使用云端 TTS”决定由云端还是 Windows 系统语音合成；Live 通话使用独立音频，与这两个开关不同。测试朗读可以在不发送聊天的情况下验证声音。", "TtsOutput", "read", "");
            add(10, "speech.output", "设置自动朗读", "希望模型回复后自动读出来，请开启“TTS 输出”。关闭会停止当前自动朗读。免打扰会暂停自动朗读，但保留此偏好；不要把免打扰导致的静音当成云端配置失败。", "TtsOutput", "read", "");
            add(10, "speech.volume", "设置音量", "先把音量设为适中的数值，并确认 Windows 当前输出设备可用、应用未静音。滑块即时保存。音量为 0 时，即使接口成功也听不到声音。", "VoiceVolume", "read", "");
            add(10, "speech.engine", "选择系统朗读或云端 TTS", "关闭“使用云端 TTS”：使用 Windows 系统语音，不需要云端 Key。\n开启：才会使用下方云端模型与音色；仅仅添加朗读模型并不会自动启用云端 TTS。想用云端，请现在明确打开此开关。", "UseCloudVoice", "read", "");
            add(10, "speech.windows", "系统朗读路径", "当前关闭云端 TTS，后续云端地址、模型、Key 步骤会自动略过。可以直接保存并测试 Windows 语音。系统缺少合适声音时，可在 Windows 语言和语音设置中安装。", "UseCloudVoice", "read", "system");
            add(10, "speech.provider", "新增云端朗读服务", "当前已开启云端 TTS。点击“新增”选择朗读厂商，确认账号已开通文字转语音服务。此处是朗读服务，不是语音识别，也不是 Live。", "AddSpeechProvider", "read", "cloud");
            add(10, "speech.url", "核对云端 TTS 地址", "填写厂商要求的 API 地址。不要填写网页地址、ASR 地址或 Live 的 WSS 地址。若请求失败，先核对这个地址。", "SpeechUrl", "url", "cloud");
            add(10, "speech.protocol", "核对朗读协议", "按厂商选择 OpenAI Audio、MiMo Chat Audio 或自动识别。部分模型使用不同音频协议；名称相似不代表接口相同。", "SpeechProtocol", "read", "cloud");
            add(10, "speech.model", "填写云端朗读模型", "确认模型 ID 是支持语音合成的模型，且账号可以调用。此页不获取模型列表，预填模型可按厂商文档修改。", "SpeechModel", "nonempty", "cloud");
            add(10, "speech.key", "填写云端朗读 Key", "填写该朗读服务的独立 Key；文字服务成功不代表 TTS 已授权。密钥会在本机加密保存，匿名自建接口可留空。", "SpeechKey", "read", "cloud");
            add(10, "speech.voice", "选择或输入音色", "从下拉列表选择，或直接输入厂商提供的音色 ID。模型与音色必须匹配。当前伙伴、服务与模型分别保存声音偏好；推荐音色仍需实际试听确认。", "SpeechVoice", "nonempty", "cloud");
            add(10, "speech.proxy", "配置朗读服务代理", "按需开启朗读服务自己的代理。文字服务的代理和更新加速不会自动替代此连接设置。无需代理时保持关闭。", "SpeechProxy", "read", "cloud");
            add(10, "speech.save", "保存朗读配置", "保存会记录当前引擎、云端服务与音色。保存成功只表示配置格式有效，不能证明服务能合成声音。下一步会提供显式试听。", "UseCloudVoice", "ai2", "");
            add(10, "speech.test", "实测：点击测试朗读", "点击高亮的“测试朗读”。它使用当前已保存的引擎、模型与音色，朗读一小段文字；云端可能消耗额度。等待测试完成后，在引导中确认是否确实听到了声音。不便播放可以跳过，不能标记为验证通过。", "PreviewSpeech", "speech-test", "");
            add(10, "speech.stop", "练习停止朗读", "测试过程中可随时点击“停止朗读”。不会关闭自动朗读偏好，也不会停止 Live。若上一小步没有声音，下一步提供逐项排错。", "StopPreviewSpeech", "read", "");
            add(10, "speech.help", "没有声音时逐项检查", "先检查系统输出设备、应用音量和此处音量；再确认是否开启云端 TTS、Key 是否属于朗读服务、模型与音色是否匹配。401/403 看授权，404 看地址和模型，超时看代理。\n自动回复不朗读时，再检查“TTS 输出”和免打扰。测试接口通过与人耳听到声音分别记录，不能互相代替。", "VoiceVolume", "read", "");
            add(11, "live.intro", "Live 与分步语音的区别", "Live 使用独立的实时模型与 WebSocket 连接，支持边说边听、字幕和语音打断，不复用普通 TTS。只需要打字或 ASR + TTS 时可以跳过本章。", "AddLiveProvider", "read", "");
            add(11, "live.provider", "选择 Live 服务", "点击“新增”选择支持的实时服务。当前实现使用 Gemini Live；不要将普通 OpenAI HTTP 地址填在此处。", "AddLiveProvider", "read", "");
            add(11, "live.url", "核对实时连接地址", "填写厂商提供的完整 WSS 地址。测试前检查防火墙、代理是否允许 WebSocket 连接。", "LiveServiceUrl", "read", "");
            add(11, "live.model", "确认实时模型与 Key", "填写可用的 Live 模型 ID，再填写该服务的 Key。模型预填值不保证你的账号已经开通权限。", "LiveServiceModel", "nonempty", "");
            add(11, "live.key", "填写 Live Key", "Live 使用自己的 Key，不自动复用文字、识别或朗读配置。保持密钥私密。", "LiveServiceKey", "read", "");
            add(11, "live.voice", "选择 Live 音色", "选择或输入实时模型支持的音色，例如 Kore；不能把普通 TTS 的音色 ID 当作必然兼容。", "LiveVoice", "nonempty", "");
            add(11, "live.proxy", "配置 Live 代理", "按需设置 Live 独立代理。连接成功后才开始收音；不要在未准备好麦克风环境时点击测试。", "LiveServiceProxy", "read", "");
            add(11, "live.save", "保存 Live 配置", "只保存，不会连接服务或启用麦克风。之后可以从这里或聊天窗口的声波按钮显式发起通话。", "LiveVoice", "ai3", "");
            add(11, "live.test", "可选：连接、说话、挂断", "点击“测试 Live 通话”会连接并在成功后收音，可能产生服务费用。请说一句话确认字幕和返回音频，然后挂断。只有观察到连接成功并挂断后，才可将本项记为连接验证通过；未测试可跳过。", "PreviewLive", "live-test", "");
            add(11, "live.mode", "选择默认语音模式", "ASR + TTS 为录音识别后再回复；Live 为实时通话。此处只选择聊天窗口的默认语音入口，不会替你拨通。", "VoiceMode", "read", "");
            add(12, "greeting.enable", "是否主动问候", "开启后伙伴按间隔偶尔主动打招呼。想保持安静可以关闭；免打扰也会暂停问候。", "GreetingEnabled", "read", "");
            add(12, "greeting.ai", "本地问候或 AI 问候", "默认可使用本地台词。开启 AI 问候会使用当前文字模型及相关聊天上下文，可能产生额外请求和费用。", "AiGreetingEnabled", "read", "");
            add(12, "greeting.interval", "设置问候间隔", "填写最短与最长间隔，单位分钟，范围 1–1440，最长不能小于最短。下一步保存这两个数字。", "GreetingMinMinutes", "greeting", "");
            add(12, "greeting.preview", "预览一次问候", "可以点击预览按钮查看真实问候气泡。若使用 AI 问候，预览可能请求模型；不需要时直接继续。", "PreviewGreeting", "read", "");
            add(13, "quiet.mode", "免打扰的作用", "免打扰暂停主动问候、散步和回复自动朗读，不会抹掉这些偏好，也不会主动挂断 Live。按需求选择。", "QuietMode", "read", "");
            add(13, "quiet.fullscreen", "全屏时自动隐藏", "只检测伙伴所在屏幕的全屏应用。退出全屏后恢复；手动隐藏后需从托盘或快捷键主动找回。", "HideOnFullscreen", "read", "");
            add(13, "quiet.recover", "穿透与锁定：先记住恢复方法", "鼠标穿透会使你无法直接点击伙伴，可通过系统托盘菜单或穿透快捷键关闭；锁定位置会禁止拖动。先知道恢复入口，再开启这些选项。", "ClickThrough", "read", "");
            add(13, "shortcut.quick", "配置快速对话快捷键", "填写组合键，例如 Ctrl + Alt + Q。留空表示停用；冲突时保留原值。“保存并继续”会尝试注册，不会偷偷替换别的程序快捷键。", "Hotkeyquick", "hotkey", "");
            add(13, "shortcut.others", "其他快捷键", "还可以单独配置显示／隐藏、免打扰、鼠标穿透。每行有自己的保存按钮；本步不会替你注册尚未确认的其他组合键。", "Hotkeyhide", "read", "");
            add(13, "history.local", "本地记录与导出", "“保存聊天记录”控制是否继续写入本机加密历史。关闭不会自动删除已有记录。完整对话右上方可导出当前记录为 Markdown，导出文件是普通可读文本，应自行妥善保存。", "SaveChatHistory", "read", "");
            add(14, "chat.open", "打开真实的完整对话窗口", "本章进入真实窗口，创建的分区、项目与草稿会保留。不会自动发送消息。操作失误可取消弹窗，或跳过当前练习。", "ChatAvatar", "read", "");
            add(14, "chat.resize", "拉宽窗口，显示更多标签", "拖动完整对话窗口边缘，把宽度拉大，或点击窗口标题栏的最大化。宽度足够后左侧栏才会出现；更宽时右侧工作面板也会展开。拉高窗口可显示更多侧栏记录，其余可在侧栏内滚动。请实际展开左侧栏再继续。小屏幕最大化后仍未出现时可跳过侧栏练习，通过输入框的项目选择器新建或选择项目。", "AgentWorkspaceSidebar", "wide", "");
            add(14, "chat.sidebar", "认识左侧栏", "左上方“新建对话”创建空白草稿。聊天分区直接管理会话，工作分区组织项目及其下属会话；悬浮或键盘聚焦行时显示轻量操作。点击会话保持原位，拖动到条目前后可调整并保存顺序。", "WorkspaceConversation", "read", "");
            add(14, "section.create", "实操：新建分区", "聊天与工作模式都支持新建分区。悬浮分区标题点击 …，或右键分区标题，选择“新建分区”并保存。工作分区的 + 新建项目，聊天分区的 + 新建对话。请创建一个测试分区，或跳过。", "SectionMore_projects", "section", "");
            add(14, "section.organize", "展开、收起与整理分区", "点击分区标题或箭头可展开、收起。分区可通过 … 或右键菜单重命名；“快速对话”“最近”等固定分组也可改名。工作项目可拖到工作分区，普通聊天可拖到聊天分区；快速窗口记录保留在快速对话中。", "ToggleSection_projects", "read", "");
            add(14, "project.create", "实操：新建项目", "先选择“工作”入口，再在目标分区标题最右侧点击 +。输入项目名称，添加实际存在的源文件夹并保存；聊天模式不显示项目文件夹。这里只添加工作目录，不会自动调用模型或执行命令。请创建一个测试项目，或跳过。", "NewProject", "project", "");
            add(14, "project.toggle", "项目是一整行按钮", "点击文件夹图标或项目名称都可展开、收起。展开文件夹与收起文件夹图标不同；点击下属对话只切换记录，不会顺便把项目收起。", "ProjectLabelsScroll", "read", "");
            add(14, "project.actions", "项目的更多操作", "悬浮项目行：… 可编辑、置顶、选择分区、在资源管理器打开、归档或移除；最右侧笔形图标是在该项目下新建对话。移除或删除前读清确认内容。", "ProjectLabelsScroll", "read", "");
            add(14, "chat.new", "实操：新建对话", "点击左上方“新建对话”。空白草稿在首次成功提交前不会作为已保存记录出现在侧栏；关闭空草稿不会新增一条记录。请创建一个新草稿。", "WorkspaceConversation", "new-chat", "");
            add(14, "chat.modes", "选择聊天或工作入口", "窗口顶部可选「聊天｜工作」入口，各自保留会话与草稿。Tab 接受预测建议，不切换入口。完整窗口的普通聊天保存在当前伙伴的默认分区或指定聊天分区；快速窗口创建的记录才进入快速对话。“最近”汇总当前伙伴聊天。两种模式均支持新建、重命名分区；聊天没有项目文件夹，工作项目与记录跨伙伴共享。切换不会自动发送草稿。", "WorkEntry", "read", "");
            add(14, "chat.work", "实操：切到工作模式", "在窗口顶部选择“工作”。输入框上方应立即出现项目栏；如果没有项目，显示“选择项目”。本步只切换，不会调用模型。", "WorkEntry", "work-mode", "");
            add(14, "project.choose", "实操：选择项目", "点击输入框上方“选择项目”，可搜索已有项目，选择“无项目”，也可从弹层新建项目。选择只应用于当前草稿，首次提交才保存归属。请打开选择器并选择一个已有项目，或跳过。", "ConversationProjectPicker", "choose-project", "");
            add(14, "chat.private", "检查对话模式隐藏项目栏", "选择顶部“聊天”，项目栏应立即隐藏，不能从 + 或 @ 菜单选择项目。返回工作入口会恢复之前的工作会话与项目。普通聊天不需要项目。", "WorkEntry", "chat-mode", "");
            add(14, "chat.attach", "添加附件", "+、粘贴或拖放可附加图片和文件，发送前可移除。图片识别需要当前模型支持。文件夹路径只是引用，不会自动读取整个目录，也不会扩大 Agent 权限。", "AddAttachment", "read", "");
            add(14, "chat.microphone", "麦克风听写的三个动作", "点击麦克风才开始录音；停止按钮会识别后填入草稿，发送按钮会识别后发送，Esc 取消。本次练习请选择停止并检查草稿，不必发送给聊天模型。", "VoiceRecord", "read", "");
            add(14, "chat.dictation", "可选实测：录音并识别成草稿", "确保识别服务已经保存、Windows 允许应用使用麦克风。点击麦克风，说一句话，再点击停止。识别返回非空文字后才算通过；取消录音或仅手动输入文字不能冒充识别成功。识别会将这段录音发给所选 ASR 服务，可能消耗额度；不方便录音可跳过。", "VoiceRecord", "dictation-test", "");
            add(14, "chat.send", "发送、换行与运行中补充", "默认 Enter 发送、Shift + Enter 换行，可在工作设置的编辑器分组更改。模型运行中，按所选方式排队或引导，Ctrl + Enter 使用相反方式；引导在可接入的边界生效，不中断当前操作。若要中断再发，明确选择“停止并立即发送”。本引导不自动发送。", "MessageInput", "read", "");
            add(14, "chat.pin", "置顶、归档与重命名", "悬浮对话行，右侧图钉用于置顶／取消置顶，归档盒用于归档。对话的更多菜单可重命名。归档用于整理列表，不等于删除历史。", "ProjectLabelsScroll", "read", "");
            add(14, "chat.export", "导出记录与长列表", "从顶部“文件”菜单选择“导出当前会话”。有较早记录时，聊天内容顶部会显示加载入口。侧栏记录多时可滚动、收起暂时不用的项目或分区，不必放大桌宠本身。", "AppMenuFile", "read", "");
            add(15, "work.scope", "先看工作设置的作用范围", "工作设置用于下一次工作请求，保存不会开始执行任务。项目设置与无项目默认设置有不同作用范围，请先读标题下的范围说明。", "WorkSettingsScope", "read", "");
            add(15, "work.directory", "设置默认工作目录", "相对路径从此目录解析。点击选择文件夹可选实际存在的目录；它不是普通聊天存放路径，也不会把已有项目自动搬走。", "AgentWorkspace", "nonempty", "");
            add(15, "work.access", "选择工作审批模式", "可选择请求批准、帮我批准或完全访问权限。新配置默认帮我批准：符合条件的例外由独立模型审核，无法确认时转人工。请求批准时，项目内常规文件操作可直接执行，越界与联网需确认。完全访问先征求确认，以当前账户权限执行，不会提权；MCP 与 GitHub 写入仍独立确认。旧配置沿用原有行为。", "AgentApprovalMode", "read", "");
            add(15, "work.plan", "计划模式只读", "需要先分析时开启计划模式，禁止写文件和打开目录等操作。关闭后才允许执行当前实现支持的修改；停止任务不会撤销已经完成的修改。", "AgentPlanMode", "read", "");
            add(15, "work.terminal", "终端与工作区沙箱", "终端默认关闭，需单独启用，不改变之前选择的审批模式。Windows 工作区沙箱隔离终端和子进程，项目可写，网络默认禁止；故障停止执行，不自动回退。宿主文件、网页与远程工具仍按各自权限执行。旧配置保持原行为。", "AgentTerminalPolicy", "read", "");
            add(15, "work.approval", "练习一次审批，不执行命令", "点击下方审批练习，核对示例命令、目录、任务和调用编号，再允许或拒绝。本练习只展示真实确认窗口，不创建进程、不修改文件，不保存可复用授权，也不表示终端已经验证。可跳过。实际命令需在以后每一次请求中重新确认。", "AgentTerminalPolicy", "approval-demo", "");
            add(15, "work.instructions", "先决定是否信任说明与技能", "仅在信任项目时开启。随后任务可读取项目范围内的 AGENTS.md，/ 菜单列出真实发现的技能；正文按需 load_skill 读取。说明会带来源与校验值，不能覆盖用户要求、扩大工具权限或自动执行脚本。未信任时不加载项目说明与项目技能；在插件页显式导入并启用的本地技能单独管理。", "AgentTrustProjectInstructions", "read", "");
            add(15, "work.skills", "可选的附加说明与技能目录", "附加说明指定一个允许读取的 UTF-8 文件；附加技能目录只发现目录下有效的 SKILL.md。可留空。不会自动安装技能或运行目录内脚本，保存设置后用于下一次任务。", "AgentSkillsDirectory", "read", "");
            add(15, "work.backup", "保留修改前备份", "建议开启自动备份。完整访问时备份在原文件旁的 .deskpet-agent-backups；受限工作目录时备份位于项目中。文件已被外部更改时会检查冲突，不应无条件覆盖。", "AgentBackupFiles", "read", "");
            add(15, "work.goal", "设置持续目标", "可写入该工作范围后续请求需要遵守的目标。目标是额外提示，不代替本次任务指令；保存不会自动运行。", "AgentGoal", "read", "");
            add(15, "work.context", "上下文自动跟随模型", "已配置模型容量时自动使用模型能力，并预留输出与工具空间。输入预算会扣除输出、安全、工具与协议开销。接近预算会压缩旧内容，摘要失败保留失败并停止该请求；界面用量是估算，摘要可能增加模型请求。无需在此重复填写已知模型容量。", "WorkContextSummary", "read", "");
            add(15, "work.fallback", "仅未知容量使用兜底值", "只有当前模型没有可用容量时才出现兜底值。按实际模型能力填写 Token 上限，不要填得高于服务能力；更换为已知容量模型后会自动使用其容量。", "AgentContextTokenLimit", "nonempty", "unknown-context");
            add(15, "work.process", "执行过程展开方式", "可控制执行过程是否默认展开。界面与编辑器偏好属于全局设置，项目编辑时需返回全局工作设置修改。", "AgentDetailedProcess", "read", "");
            add(15, "editor.prediction", "显示预测消息", "在编辑器分组选择是否显示预测消息，默认开启。模型会根据最近对话预测下一条输入，可能产生额外请求。预测内容先进入草稿，不会自动发送；不需要时可关闭。", "ShowPredictedMessages", "read", "");
            add(15, "editor.markdown", "选择输入区编辑格式", "纯文本编辑器默认关闭：直接编辑粗体、标题、列表、代码和链接，隐藏 Markdown 标记。行内格式末尾输入空格或换行后，后续文字回到普通格式；代码、列表、引用后的草稿换行会保留。开启后按原始语法编辑。切换保留草稿；只改变输入方式，不会关闭发送后消息的 Markdown 显示。", "PlainTextEditor", "read", "");
            add(15, "editor.context", "显示或隐藏上下文用量", "开启后，模型选择器旁显示用量圆环，可查看上下文估算与压缩预算。关闭只隐藏指示器，不会停用自动压缩。模型容量仍在模型配置中填写。", "ShowContextUsage", "read", "");
            add(15, "editor.send", "选择发送快捷键", "Enter 发送时使用 Shift + Enter 换行；Ctrl + Enter 发送时，单独 Enter 换行。更改后需保存。输入法仍在选字时不会提交消息。按钮发送不受快捷键选择影响。", "SendShortcut", "read", "");
            add(15, "editor.followup", "选择运行中跟进方式", "排队会等本轮完成再处理；引导会继续当前已开始的操作，在下一处可调整的工具或模型请求边界接入纠偏，不取消任务。已经发出的模型请求不能中途修改。运行中 Ctrl + Enter 使用相反方式；停止并立即发送需明确选择。", "FollowUpBehavior", "read", "");
            add(15, "work.boundary", "确认当前 Agent 能力边界", "当前桌面端支持已接入的文件与目录工具、搜索和文件修改。不能把模型文字里的“已运行”当作执行证据。终端需单独启用并遵循审批与沙箱设置，MCP 必须主动连接，子任务只读，GitHub 需配置实际仓库且写入按次确认。未开放的工具不会因为提示词而获得。", "WorkSettingsPanel", "read", "");
            add(15, "work.workers", "独立只读子任务", "模型支持工具且开启工作模式时，父任务可以委派真实 explore worker。最多四个并行、一级深度，其余排队；各自拥有历史、工具与预算，并继承父任务拒绝规则。它们不能写文件、执行命令或继续派生。停止父任务也会停止它们；结果与累计用量在任务面板查看。", "WorkSettingsPanel", "read", "");
            add(15, "work.recovery", "以执行证据核对结果", "任务面板展示真实文件变更、命令退出码、输出和独立 worker 结果。中断后若操作可能已经发生，会显示待核对并停止后续调用；先检查文件或外部结果，再点击已核对执行记录。不会盲目重放旧命令或沿用旧审批。", "WorkSettingsPanel", "read", "");
            add(15, "work.facts", "项目事实由你手动维护", "任务面板的项目事实可手动新增、编辑和删除，保留来源任务／文件与时间；仅供同项目后续任务引用。删除后不再注入。不会自动沉淀长期记忆，也不会从模型结论推断验证成功。", "WorkSettingsPanel", "read", "");
            add(15, "work.save", "保存工作设置", "点击“保存并继续”验证目录、兜底值等并保存。本步不执行文件工具。保存失败时停留在这里，可以修正或跳过。", "SaveWorkSettings", "work-save", "");
            add(15, "work.prompt", "单独配置工作提示词", "切换到“工作提示词”标签。所有桌宠与项目的工作模式共用它；普通聊天仍使用各自人格。提示词不能扩大文件权限，也不能启用未接入的工具。", "AgentSystemPrompt", "read", "");
            add(15, "work.prompt-save", "保存工作提示词", "可保留默认值，或填写自己的工作风格与结果要求。不能为空。“保存并继续”只保存此标签的工作提示词，不覆盖前面尚未保存的其他设置。", "AgentSystemPrompt", "prompt-save", "");
            add(15, "mcp.intro", "可选：连接你信任的 MCP 服务器", "不使用扩展可跳过这些步骤。在左侧插件页的 MCP 标签点击添加服务器，填写独立配置。保存和重开应用都不会自动连接；stdio 仅在主动连接时启动所填可执行文件。计划模式不开放 MCP 工具。", "AddMcpServer", "read", "");
            add(15, "mcp.transport", "核对协议与目标", "当前支持标注的 stdio 和 HTTP JSON 子集，HTTP SSE 不支持。HTTP 填 HTTPS 服务地址；stdio 填已有程序绝对路径、JSON 参数数组和工作目录。不要把密钥写进参数。", "McpServerTransport", "read", "");
            add(15, "mcp.credentials", "使用独立凭证并保存", "HTTP 凭证单独填写，在本地加密保存，不复用文字模型密钥。手动点击保存配置；有误时先修正。保存成功只证明本地配置保存，不代表连接、工具调用或账号权限已通过验证。", "McpServerKey", "read", "");
